def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-length, uniform separator lines partition the canvas into tiles.
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_bounds = [-1] + rows + [h]
    col_bounds = [-1] + cols + [w]
    tiles = []
    for ri in range(len(row_bounds)-1):
        r0, r1 = row_bounds[ri]+1, row_bounds[ri+1]
        if r0 >= r1: continue
        for ci in range(len(col_bounds)-1):
            c0, c1 = col_bounds[ci]+1, col_bounds[ci+1]
            if c0 < c1:
                tiles.append((r0,r1,c0,c1))
    if not tiles:
        return [row[:] for row in grid]
    # The tile containing the most non-background marks is the pattern source.
    separator_colors = {grid[r][0] for r in rows} | {grid[0][c] for c in cols}
    counts = Counter(v for row in grid for v in row if v not in separator_colors)
    background = counts.most_common(1)[0][0] if counts else 0
    def score(t):
        a,b,c,d=t
        return sum(grid[r][col] != background for r in range(a,b) for col in range(c,d))
    source = max(tiles, key=score)
    sr0,sr1,sc0,sc1=source
    pattern=[row[sc0:sc1] for row in grid[sr0:sr1]]
    out=[row[:] for row in grid]
    for r0,r1,c0,c1 in tiles:
        if r1-r0 != len(pattern) or c1-c0 != len(pattern[0]):
            continue
        for dr in range(r1-r0):
            for dc in range(c1-c0):
                out[r0+dr][c0+dc]=pattern[dr][dc]
    return out

